  "description": "typed handle, shape `{kind, id, parent?}`. Examples:\n`{\"kind\": \"spec\", \"id\": \"openapi.yaml\"}`,\n`{\"kind\": \"variable\", \"id\": \"access_token\"}`.",
  "anyOf": [
    {"additionalProperties": {}, "type": "object"},
    {"type": "string"}
